definitions.code:
FxAppend:
    private:
        @: first
        @: second
    return: @
    append:
        throws: copy(FxThrows\sequence)
        private: @: empty (copy(()))
        return: FxSeqConcat\concat(parts := (empty; first; second))

FxEqualFields:
    private:
        @: first
        @: second
        @: same 0
    required: first second
    return: int
    equalFields:
        throws: copy(FxThrows\predicate)
        FxSeqInfo\get(first)
        FxSeqInfo\get(second)
        if: length(first) != length(second)
            return: 0
        return: FxSequenceDifference\find(
            first := first;
            second := second;
            same := same;
            count := length(first)
        ) < 0

FxFullPolicy:
    private: @: operation
    return: @
    make:
        throws: copy(FxThrows\adapter)
        private: @: info FxKernel\signature(operation)
        private: @: empty (copy(()))
        return: FxSourcePolicy\make(operation; FxIndices\make(0; length(info\inputTypes)); empty; empty; empty)

FxPipeBuild:
    private:
        @: inputType
        @: stages
    required: inputType stages
    return: @
    make:
        throws: copy(FxThrows\adapter)
        private: @: resultType FxKernel\normalizeType(inputType)
        private: @: failures (copy(()))
        private: int: i 0
        while: i < length(stages)
            private: @: operation \FxSeqRead\read(stages; i)
            private: @: shape FxKernel\signature(operation)
            if: length(shape\inputTypes) != 1 || shape\hasResult = 0
                throw: FxArity()
            resultType := shape\resultType
            failures := FxFailures\union(failures; shape\throws)
            i += 1
        private: @: input FxKernel\normalizeType(inputType)
        private: @: contract FxSignatures\make(FxOne\make(input); resultType)
        private: @: state (copy(FxPipeState))
        state\stages := FxSeqRecords\make(stages)
        return: FxWrap\make(contract; FxPipeEngine\run; state; failures)

FxPipeEngine:
    private:
        @: state
        @: frame
    return: @
    run:
        throws: copy(FxThrows\call) FxArity ReceiverIndex
        private: @: slot FxKernel\frameSlot(frame; 0; 1)
        return: FxPipe\pipe(slot\value; state\stages)

FxPredicate:
    private: @: operation
    return: @
    predicate:
        throws: copy(FxThrows\adapter)
        private: @: info FxKernel\signature(subject := operation)
        private: @: booleanType FxKernel\normalizeType(token := FxBooleanToken[0])
        private: @: contract FxSignatures\make(info\inputTypes; booleanType)
        private: @: state (copy(FxPredicateState))
        state\operation := operation
        return: FxWrap\make(contract; FxPredicateEngine\run; state; info\throws; FxFullPolicy\make(operation))

FxPredicateEngine:
    private:
        @: state
        @: frame
    return: @
    run:
        throws: copy(FxThrows\recordcall)
        private: @: record FxFrameApply\apply(frame)
        private: int: truth \record
        return: ((truth != 0) FxRecordOperands\record)

FxTry:
    private:
        @: operation
        @: args
    return: @
    attempt:
        throws: copy(FxThrows\kernel)
        private: @: info FxKernel\signature(subject := operation)
        return: FxKernel\attempt(operation; args; info\throws)

FxValueSame:
    private:
        @: first
        @: second
        @: same 0
    required: first second
    return: int
    test:
        throws: copy(FxThrows\predicate)
        if: same != 0
            return: FxSeqPredicate\truth(FxApply\apply(same; FxTwo\make(first; second)))
        private: int: firstArray FxKernel\acceptsRequirement(
            candidate := first;
            requirement := FxEqualityTypes\array[0]
        )
        private: int: secondArray FxKernel\acceptsRequirement(
            candidate := second;
            requirement := FxEqualityTypes\array[0]
        )
        if: firstArray != secondArray
            return: 0
        if: firstArray != 0
            return: FxEqualFields\equalFields(first; second)
        return: \first = \second

FxWrap:
    private:
        @: contract
        @: engine
        @: payload
        @: failures
        @: policy 0
    return: @
    make:
        throws: copy(FxThrows\selection)
        private: @: info FxKernel\signature(subject := contract)
        private: @: state (copy(FxEngineState))
        state\engine := engine
        state\payload := payload
        private: char[]: text "private: @: fx_frame FxKernel\\currentCall(node)\nprivate: @: fx_engine node\\private\\state\\engine\nprivate: @: fx_answer fx_engine(state := node\\private\\state\\payload; frame := fx_frame)\n"
        if: info\hasResult != 0
            text := FxConcat\concat(text; "return: \\fx_answer\n")
        else:
            text := FxConcat\concat(text; "return\n")
        text := FxConcat\concat(text; "catch: FxCallFailure (@: outcome)\n    FxKernel\\raise(name := outcome\\failure; payload := outcome\\payload)\n")
        private: @: engineInfo FxKernel\signature(subject := engine)
        private: @: escapingEngine FxFailureFilter\without(engineInfo\throws; "FxCallFailure")
        private: @: allFailures FxFailures\union(failures; FxStageFailures\names())
        allFailures := FxFailures\union(allFailures; escapingEngine)
        return: FxBuild\make(contract; text; state; allFailures; policy)

